import{_ as i,C as r,o as l,c as n,a2 as a,b as s,w as e,a as E,E as B,a3 as d}from"./chunks/framework.BBdhqAg0.js";const g="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"MAIL 발송 관리","description":"","frontmatter":{},"headers":[],"relativePath":"notice/mailing.md","filePath":"notice/mailing.md","lastUpdated":1793125015000}'),A={name:"notice/mailing.md"};function C(c,t,h,u,p,m){const o=r("Mermaid");return l(),n("div",null,[t[1]||(t[1]=a('<h1 id="mail-발송-관리" tabindex="-1">MAIL 발송 관리 <a class="header-anchor" href="#mail-발송-관리" aria-label="Permalink to &quot;MAIL 발송 관리&quot;">​</a></h1><p>프로젝트 계약자 또는 임의의 외부 수신자에게 공식 안내문, 소식지, 분담금 납부 안내 등을 대량 이메일(HTML)로 발송하고 그 이력을 추적·관리하는 화면입니다.</p><ul><li><strong>위치</strong>: <code>고객 고지 관리 &gt; MAIL 발송 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+g+'" alt="MAIL 발송 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/mailing.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>문자 메시지(SMS/LMS)의 글자 수 한계와 비용 부담을 보완하여, 서식과 표, 이미지가 포함된 완성도 높은 공식 안내문을 이메일로 대량 발송할 수 있습니다. 위지윅(WYSIWYG) 리치 텍스트 서식 에디터, 계약자 정보 자동 치환 태그, 수신 대상자별 이메일 주소 직접 수정 및 외부 관계자 수기 추가 기능, 그리고 대량 발송을 안정적으로 처리하는 백그라운드 비동기 발송 엔진 및 상세 전송 결과(성공/실패 내역) 조회를 지원합니다.</p>',6)),(l(),s(d,null,{default:e(()=>[B(o,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EB%8C%80%EC%83%81%20%ED%95%84%ED%84%B0%EB%A7%81%3Cbr%2F%3E(%EC%B0%A8%EC%88%98%C2%B7%EB%8F%99%EB%B3%84%20%EA%B3%84%EC%95%BD%EC%9E%90%20%EC%B6%94%EC%B6%9C)%22%5D%20--%3E%20B%5B%222.%20%EC%88%98%EC%8B%A0%EC%9E%90%20%EA%B2%80%ED%86%A0%C2%B7%EB%B3%B4%EC%99%84%3Cbr%2F%3E(%EB%88%84%EB%9D%BD%20%EC%9D%B4%EB%A9%94%EC%9D%BC%20%EB%93%B1%EB%A1%9D%C2%B7%EC%99%B8%EB%B6%80%EC%9D%B8%20%EC%B6%94%EA%B0%80)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EB%B3%B8%EB%AC%B8%20%EC%9E%91%EC%84%B1%20%EB%B0%8F%20%EC%84%9C%EC%8B%9D%3Cbr%2F%3E(%EB%A6%AC%EC%B9%98%20%EC%97%90%EB%94%94%ED%84%B0%C2%B7%EB%A8%B8%EC%A7%80%20%ED%83%9C%EA%B7%B8)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%82%AC%EC%A0%84%201%EA%B1%B4%20%ED%85%8C%EC%8A%A4%ED%8A%B8%20%EB%B0%9C%EC%86%A1%3Cbr%2F%3E(%EB%A0%88%EC%9D%B4%EC%95%84%EC%9B%83%20%EB%B0%8F%20%EC%98%A4%ED%83%88%EC%9E%90%20%EA%B2%80%EC%A6%9D)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EB%B0%B1%EA%B7%B8%EB%9D%BC%EC%9A%B4%EB%93%9C%20%EB%8C%80%EB%9F%89%20%EB%B0%9C%EC%86%A1%3Cbr%2F%3E(%EC%A0%84%EC%86%A1%20%EC%9D%B4%EB%A0%A5%20%EB%B0%8F%20%EC%84%B1%EA%B3%B5%2F%EC%8B%A4%ED%8C%A8%20%EC%B6%94%EC%A0%81)%22%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[E(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>타깃 필터링 및 수신자 자동 추출</strong>: 프로젝트 내 특정 차수 또는 동을 지정하여 해당 계약자 이메일 목록을 즉시 추출</li><li><strong>유연한 수신 대상자 정밀 관리</strong>: <ul><li>이메일 주소가 비어있는 계약자 확인 및 인라인 이메일 주소 즉시 등록/수정</li><li>개별 수신자의 이번 발송 대상 포함/제외 토글</li><li>은행, 신탁사, 시공사 등 외부 관계자 이메일 수기 추가 기능</li></ul></li><li><strong>리치 텍스트(HTML) 서식 에디터 내장</strong>: 제목, 본문 글자 스타일(크기, 굵기, 색상, 정렬 등), 인용구, 번호 목록, 하이퍼링크 및 이미지 첨부 지원</li><li><strong>동적 머지 태그(Merge Tags) 치환</strong>: 계약자 성명, 계약 동호수, 프로젝트 명칭 등을 치환 코드로 작성하여 개인별 맞춤 안내문 자동 생성</li><li><strong>안정적인 백그라운드 비동기 대량 발송</strong>: 수백·수천 통의 메일 발송 시에도 화면 멈춤이나 대기 지연 없이 백그라운드 엔진을 통해 순차 전송</li><li><strong>상세 발송 이력 및 전송 결과 대장</strong>: <ul><li>발송 일시, 발송자, 제목, 총 대상자 수, 성공/실패 건수 실시간 집계</li><li>상세 보기: 실제 발송된 서식 본문 렌더링 미리보기, HTML 원문 코드 확인, 수신자별 전송 성공 여부 및 실패 원인(오류 로그) 확인</li></ul></li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><p>상단 탭을 통해 **[MAIL 발송]**과 <strong>[발송 내역]</strong> 화면으로 전환할 수 있습니다.</p><h3 id="_1-mail-발송-탭" tabindex="-1">1. MAIL 발송 (탭) <a class="header-anchor" href="#_1-mail-발송-탭" aria-label="Permalink to &quot;1. MAIL 발송 (탭)&quot;">​</a></h3><p>메일 수신 대상자를 선정하고 본문 서식을 작성하여 발송하는 화면입니다.</p><h4 id="_1-발송-기본-정보-및-수신자-설정" tabindex="-1">① 발송 기본 정보 및 수신자 설정 <a class="header-anchor" href="#_1-발송-기본-정보-및-수신자-설정" aria-label="Permalink to &quot;① 발송 기본 정보 및 수신자 설정&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">상세 설명 및 실무 팁</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>차수 / 동 선택</strong></td><td style="text-align:left;">메일을 발송할 대상 차수 및 동을 필터링하여 계약자를 추출합니다.</td></tr><tr><td style="text-align:left;"><strong>수신 대상자 관리 버튼</strong></td><td style="text-align:left;">추출된 계약자 명단 모달을 열어 이메일 주소를 점검·수정하거나 특정인을 발송 대상에서 제외합니다.</td></tr><tr><td style="text-align:left;"><strong>발송자 (From)</strong></td><td style="text-align:left;">시스템 로그인 사용자의 이름과 사전 등록된 대표 발송 메일 주소로 구성됩니다.</td></tr><tr><td style="text-align:left;"><strong>안내 메일 제목</strong></td><td style="text-align:left;">수신자의 이메일 편지함에 노출될 메일 제목을 명확하고 신뢰성 있게 입력합니다.</td></tr></tbody></table><h4 id="_2-본문-작성-리치-에디터-및-치환-태그" tabindex="-1">② 본문 작성 (리치 에디터) 및 치환 태그 <a class="header-anchor" href="#_2-본문-작성-리치-에디터-및-치환-태그" aria-label="Permalink to &quot;② 본문 작성 (리치 에디터) 및 치환 태그&quot;">​</a></h4><ul><li><strong>서식 도구함</strong>: 폰트 크기, 제목 서식(H1~H3), 굵게(B), 기울임, 밑줄, 글자색 및 배경색, 정렬, 번호 목록, 하이퍼링크, 이미지 첨부 등 제공</li><li><strong>머지 태그(치환 변수) 안내</strong>: <ul><li><span><code>{{ 계약자명 }}</code></span>: 수신 계약자의 실제 성명으로 자동 변환</li><li><span><code>{{ 동호수 }}</code></span>: 해당 계약자의 동·호수(배치 전일 경우 계약 일련번호)로 자동 변환</li><li><span><code>{{ 프로젝트명 }}</code></span>: 현재 선택된 사업지 명칭으로 자동 변환</li></ul></li></ul><h4 id="_3-수신-대상자-관리-모달" tabindex="-1">③ 수신 대상자 관리 모달 <a class="header-anchor" href="#_3-수신-대상자-관리-모달" aria-label="Permalink to &quot;③ 수신 대상자 관리 모달&quot;">​</a></h4><p>[수신 대상자 확인] 버튼을 누르면 열리는 팝업창으로, 실제 메일을 수신할 명단을 꼼꼼하게 점검합니다.</p><ul><li><strong>이메일 주소 인라인 수정</strong>: 이메일이 등록되지 않았거나 변경된 계약자는 테이블 내에서 직접 이메일 주소를 입력하여 즉시 반영할 수 있습니다.</li><li><strong>체크박스 선택/해제</strong>: 특정 계약자를 이번 발송에서 제외하려면 체크를 해제합니다.</li><li><strong>외부 수신자 직접 추가</strong>: 상단의 [수신자 추가] 영역에서 성명, 이메일, 비고를 입력하여 계약자 명단 외의 관계자(금융기관, 대행사 담당자 등)를 수신인에 포함할 수 있습니다.</li></ul><h3 id="_2-발송-내역-탭" tabindex="-1">2. 발송 내역 (탭) <a class="header-anchor" href="#_2-발송-내역-탭" aria-label="Permalink to &quot;2. 발송 내역 (탭)&quot;">​</a></h3><p>지금까지 발송된 모든 대량 이메일의 기록을 조회하고 결과를 점검합니다.</p><ul><li><strong>발송 이력 목록</strong>: <ul><li><strong>발송일시</strong>: 메일 발송이 접수되어 전송 처리된 일시</li><li><strong>프로젝트 및 발송자</strong>: 메일을 발송한 프로젝트와 발송 실행 사용자 계정</li><li><strong>제목</strong>: 발송된 이메일 제목</li><li><strong>전송 통계</strong>: 총 발송 대상 수, 성공 건수, 실패 건수를 배지로 직관적 표시</li><li><strong>상세보기</strong>: [상세보기] 버튼 클릭 시 발송 상세 모달 호출</li></ul></li><li><strong>발송 상세 모달</strong>: <ul><li><strong>발송 정보 요약</strong>: 프로젝트, 발송자, 발송일시, 최종 성공/실패 통계</li><li><strong>발송 본문 확인</strong>: 실제 발송된 서식 본문 렌더링을 미리 볼 수 있으며, 머지 태그가 어떻게 적용되었는지 확인 가능합니다. (필요시 [HTML 코드 보기] 토글로 원문 확인)</li><li><strong>수신자별 전송 결과 테이블</strong>: 수신자명, 이메일 주소, 전송 상태(성공/실패), 오류 발생 시 상세 사유(예: 유효하지 않은 메일 주소 형식, 수신 서버 거부 등) 기록 제공</li></ul></li></ul><h2 id="💡-실무-활용-팁-및-주의-사항" tabindex="-1">💡 실무 활용 팁 및 주의 사항 <a class="header-anchor" href="#💡-실무-활용-팁-및-주의-사항" aria-label="Permalink to &quot;💡 실무 활용 팁 및 주의 사항&quot;">​</a></h2><ul><li><strong>본인 이메일로 1건 사전 테스트 발송 필수</strong>: 수백 명의 계약자에게 대량 전송하기 전, [수신 대상자 관리]에서 계약자 선택을 모두 해제하고 <strong>본인(담당자)의 이메일만 1건 추가</strong>하여 시험 발송하세요. PC와 모바일 메일 앱에서 줄바꿈, 이미지 표시, 폰트 크기가 자연스러운지 직접 확인하는 것이 실수를 예방하는 가장 확실한 방법입니다.</li><li><strong>이메일 주소 유효성 사전 검토</strong>: 주소에 공백이 포함되어 있거나 <code>@</code> 또는 도메인(<code>.com</code>, <code>.net</code>)이 누락된 주소는 발송 엔진에서 즉시 실패 처리됩니다. [수신 대상자 관리] 모달에서 이메일 형식 오류를 미리 수정하세요.</li><li><strong>치환 태그 정확한 표기 준수</strong>: 머지 태그는 <span><code>{{ 계약자명 }}</code></span>, <span><code>{{ 동호수 }}</code></span>, <span><code>{{ 프로젝트명 }}</code></span>과 같이 중괄호 2개를 정확히 감싸야 치환 엔진이 올바르게 인식합니다. 중괄호가 1개만 입력되면 태그가 텍스트 그대로 노출될 수 있으니 주의하세요.</li><li><strong>대용량 이미지 주의</strong>: 본문에 삽입하는 이미지는 용량이 너무 크면 수신자의 메일 로딩이 느려지거나 스팸 메일함으로 자동 분류될 수 있습니다. 웹용으로 적절히 최적화된 이미지(가로폭 800px 이하 권장)를 사용하는 것이 좋습니다.</li></ul>',18))])}const f=i(A,[["render",C]]);export{b as __pageData,f as default};
